use xiom.io;
fn is_friend(friends: &Vec[Str], name: Str) -> Bool {
  let i = 0;
  while i < friends.len() {
    let f = match friends.get(i) { Some(n) => n, None => "" };
    if f == name {
      return true;
    }
    i = i + 1;
  }
  return false;
}

fn main() -> Int {
  let friends: Vec[Str] = Vec[Str].new();
  friends.push("Tom");
  friends.push("Lisa");
  friends.push("Aisha");
  friends.push("Miguel");

  let i = 0;
  while i < friends.len() {
    let f = match friends.get(i) { Some(n) => n, None => "" };
    io.println("Friend: " + f);
    i = i + 1;
  }

  io.println((is_friend(&friends, "Tom")).to_str());
  io.println(friends.len().to_str());
  return 0;
}
